import { useState } from "react";

import "./Users.css";

function Users() {
  const [user, setUser] = useState([]);

  fetch("https://673b986796b8dcd5f3f6e23a.mockapi.io/dataForReact")
    .than((res) => res.json())
    .than((res) => setUser(res));

  return (
    <div>
      <p>{user.map((elm) => elm.name)}</p>
    </div>
  );
}

export default Users;
